python -I - <<'PY'
import json, collections, ast
from pathlib import Path
import pyarrow.parquet as pq
root=Path('/workspace/data/AgentWorldModel-1K')
tasks={r['scenario']:r['tasks'] for r in map(json.loads,(root/'gen_tasks.jsonl').open())}
rows=list(map(json.loads,(root/'gen_verifier.pure_code.jsonl').open()))
by=collections.defaultdict(list)
for line,r in enumerate(rows,1): by[(r['scenario'],r['task_idx'])].append((line,r))
splits={s:pq.read_table(root/f'verl/{s}.parquet').to_pylist() for s in ['train','test']}
keys={s:collections.defaultdict(list) for s in splits}
for s,rr in splits.items():
 for i,row in enumerate(rr):
  e=row['env_kwargs']; keys[s][(e['scenario'],e['task_idx'])].append((i,e['task']))
for key,v in by.items():
 if len(v)<2: continue
 print('\n===',key,'===')
 print('canonical task:',tasks[key[0]][key[1]])
 for s in ['train','test']:
  if key in keys[s]: print(s,keys[s][key])
 for line,r in v:
  ver=r['verification']
  try:
   obj=ast.literal_eval(ver) if isinstance(ver,str) else ver
   code=obj.get('code','') if isinstance(obj,dict) else ''
  except Exception as e: code=f'PARSE ERROR {e}'
  print('line',line,'task=',r['task'])
  print('task matches canonical?',r['task']==tasks[key[0]][key[1]],'code chars',len(code),'code sha',__import__('hashlib').sha256(code.encode()).hexdigest()[:16])
  print('code head:',code[:500].replace('\n','\\n'))
PY

