import ast
import json
import sqlite3
import sys
from collections import defaultdict
from pathlib import Path

ROOT = Path('/workspace/data/AgentWorldModel-1K')
SCENARIOS = {
    'q_a_knowledge_base_1', 'personal_finance_management_1',
    'donation_fundraising_platform_1', 'ticketing_and_access_management_1',
    'peer_to_peer_payments_1', 'social_platform_1', 'property_management_3',
    'asset_management_1', 'loyalty_and_rewards_1',
}

def load_selected(name):
    selected = {}
    with (ROOT / name).open() as stream:
        for line in stream:
            row = json.loads(line)
            if row['scenario'] in SCENARIOS:
                selected[row['scenario']] = row
    return selected

def build_db(scenario, schemas, samples, directory):
    path = directory / f'{scenario}.db'
    conn = sqlite3.connect(path)
    try:
        for table in schemas[scenario]['db_schema']['tables']:
            try:
                conn.execute(table['ddl'])
                for statement in table.get('indexes', []) + table.get('examples', []):
                    conn.execute(statement)
            except Exception as exc:
                print('DDL ERROR', scenario, table.get('name'), repr(exc))
        good = bad = 0
        for table in samples[scenario]['sample_data']['tables']:
            for statement in table.get('insert_statements', []):
                try:
                    conn.execute(statement)
                    good += 1
                except Exception:
                    bad += 1
        conn.commit()
        print('BUILT', scenario, 'inserts', good, 'failed', bad)
    finally:
        conn.close()
    return path

def get_code(row):
    verification = row['verification']
    if isinstance(verification, str):
        verification = ast.literal_eval(verification)
    return verification['code']

def run(code, initial, final):
    namespace = {}
    try:
        exec(code, namespace)
        result = namespace['verify_task_completion'](str(initial), str(final), '')
        return json.dumps(result, default=str)[:800]
    except Exception as exc:
        return f'ERROR {type(exc).__name__}: {exc}'

def main():
    directory = Path(sys.argv[1])
    directory.mkdir(parents=True, exist_ok=True)
    schemas = load_selected('gen_db.jsonl')
    samples = load_selected('gen_sample.jsonl')
    paths = {s: build_db(s, schemas, samples, directory) for s in sorted(SCENARIOS)}
    grouped = defaultdict(list)
    with (ROOT / 'gen_verifier.pure_code.jsonl').open() as stream:
        for line_number, line in enumerate(stream, 1):
            row = json.loads(line)
            grouped[(row['scenario'], row['task_idx'])].append((line_number, row))
    for (scenario, task_idx), rows in grouped.items():
        if len(rows) < 2:
            continue
        print('\nCASE', scenario, task_idx)
        for line_number, row in rows:
            outcome = run(get_code(row), paths[scenario], paths[scenario])
            print('line', line_number, 'unchanged DB =>', outcome)

if __name__ == '__main__':
    main()

