            rows = cur.fetchall()
            conn.close()
            return rows
        except Exception:
            return []

    # Helper: parse final_answer to mapping {event_id:int -> set(pass_ids:int)}
    def parse_event_pass_map(ans: str) -> dict | None:
        if not isinstance(ans, str):
            return None
        s = ans.strip()
        if not s:
            return None

        # Try to extract JSON from the answer by locating the outermost braces
        def try_json_extract(text: str):
            # Direct parse first
            try:
                return json.loads(text)
            except Exception:
                pass
            # Find first '{' and last '}'
            l = text.find('{')
            r = text.rfind('}')
            if l != -1 and r != -1 and r > l:
                blob = text[l:r+1]
                try:
                    return json.loads(blob)
                except Exception:
                    return None
            return None

        def build_map_from_obj(obj):
            # Returns dict[int, set[int]] or None
            mapping: dict[int, set[int]] = {}
            if isinstance(obj, dict):
                # Case 1: top-level keys are event IDs
                all_digit_keys = all(isinstance(k, (str,int)) and str(k).isdigit() for k in obj.keys()) and len(obj.keys())>0
                if all_digit_keys:
                    for k, v in obj.items():
                        try:
                            eid = int(k)
                        except Exception:
                            continue
                        pass_ids: set[int] = set()
                        if isinstance(v, list):
                            for item in v:
