                                            pass_ids.add(int(item[key]))
                                            break
                                elif isinstance(item, (int, str)) and str(item).isdigit():
                                    pass_ids.add(int(item))
                        if pass_ids:
                            mapping[eid] = pass_ids
                    if mapping:
                        return mapping
                # Case 2: look for a list value containing groups with event_id and passes
                for v in obj.values():
                    if isinstance(v, list):
                        tmp = build_map_from_list(v)
                        if tmp:
                            return tmp
                return None
            elif isinstance(obj, list):
                return build_map_from_list(obj)
            return None

        def build_map_from_list(lst):
            mapping: dict[int, set[int]] = {}
            for item in lst:
                if isinstance(item, dict):
                    # Expect fields like event_id / eventId and passes list
                    eid = None
                    for k in ("event_id", "eventId", "eventID", "event"):
                        if k in item and isinstance(item[k], (int, str)) and str(item[k]).isdigit():
                            eid = int(item[k])
                            break
                    if eid is None:
                        continue
                    passes = None
                    for pk in ("passes", "accesses", "items", "entries"):
                        if pk in item and isinstance(item[pk], list):
                            passes = item[pk]
